    ('d69d7ad3-c7ab-5f8f-8b17-753068e3c663'::uuid, 'EMOTION', '감정', '감정의 이름, 강도, 몸의 신호를 살펴봅니다.', 1),
    ('fa04e69d-1015-59d3-b486-f1bf8583263c'::uuid, 'THOUGHT', '생각', '떠오른 생각과 해석의 가능성을 살펴봅니다.', 2),
    ('3f3fba80-3277-59ed-ac3a-7e8f88d7b773'::uuid, 'RELATIONSHIP', '관계', '관계 안에서 느낀 감정과 원하는 경계를 살펴봅니다.', 3),
    ('6dd18c38-af04-52bc-9eae-f73773d92710'::uuid, 'FOCUS', '집중', '집중을 돕거나 방해하는 조건을 살펴봅니다.', 4),
    ('2cf1dc3f-1c78-556f-925b-b45125f5e95a'::uuid, 'START_EXECUTION', '시작과 실행', '의지보다 시작을 돕는 구체적인 조건을 찾아봅니다.', 5),
    ('2c789c3f-d1a7-5d64-b07a-4c847c9523c9'::uuid, 'REST', '휴식', '나에게 실제로 도움이 되는 회복 방식을 살펴봅니다.', 6),
    ('34474694-da41-5a99-9108-aecfd21a5de4'::uuid, 'LIFE_RHYTHM', '생활 리듬', '수면, 아침, 반복 행동의 단서를 살펴봅니다.', 7),
    ('29d3e25a-3f99-5de0-80ec-59cc603b9dc3'::uuid, 'ENVIRONMENT', '환경', '공간과 도구가 감정과 행동에 미치는 영향을 살펴봅니다.', 8),
    ('89c16867-28e4-5363-9f1b-2bec8a55bd45'::uuid, 'SELF_TRUST', '자기신뢰', '실제 행동과 선택에서 나를 믿을 근거를 찾아봅니다.', 9),
    ('f60e0e2d-e3c8-50b4-aa77-7816a90c055d'::uuid, 'TRAIT', '나의 특성', '자신을 규정하지 않고 반복된다고 느끼는 특성을 관찰합니다.', 10),
    ('34132496-1861-5a71-9311-0e6f52b4f743'::uuid, 'CONVERSATION', '대화', '말하기와 듣기에서 나에게 맞는 방식을 살펴봅니다.', 11),
    ('b0dc96d8-76c6-519a-bd67-773174ba72ee'::uuid, 'GRATITUDE', '감사', '감사하거나 다행이었던 경험이 왜 중요했는지 살펴봅니다.', 12),
    ('df555650-f131-5fcc-8f9d-f9ca6d573ee8'::uuid, 'VALUE_STANDARD', '가치와 기준', '타인의 기대와 구분되는 나의 기준을 살펴봅니다.', 13);

INSERT INTO experiment_missions
    (id, code, content_version, topic_id, title, description, instruction,
     mission_type, response_type, estimated_minutes, emotional_load,
     reflection_questions, examples, response_schema, safety_note)
VALUES
    ('aac55f90-7c2c-59c6-906c-20db74fe4152'::uuid, 'EMOTION_WORD', 1, 'd69d7ad3-c7ab-5f8f-8b17-753068e3c663'::uuid, '감정 알아차리기', '지금 느껴지는 감정에 가볍게 이름을 붙여봅니다.', '지금의 감정을 한두 단어로 적어보세요.', 'OBSERVATION', 'TEXT', 3, 'LOW', '["그 감정은 언제부터 느껴졌나요?","몸에서도 달라진 점이 있었나요?"]'::jsonb, '["안도감","답답함","설렘과 걱정"]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('86063cf3-ca15-5974-8c6a-6fa31f243640'::uuid, 'CALM_MOMENT', 1, '2c789c3f-d1a7-5d64-b07a-4c847c9523c9'::uuid, '편안한 순간 찾기', '아주 짧았더라도 편안했던 순간의 조건을 찾아봅니다.', '오늘 조금이라도 편안했던 순간 하나를 기록해보세요.', 'OBSERVATION', 'TEXT', 3, 'LOW', '["그 순간에는 무엇이 있었나요?","다시 만들 수 있는 조건이 있나요?"]'::jsonb, '["조용히 커피를 마신 순간","혼자 있을 수 있었던 시간"]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('c00beb77-28ac-59f9-a09b-10b408b6f564'::uuid, 'LOWER_EXPECTATION', 1, '2cf1dc3f-1c78-556f-925b-b45125f5e95a'::uuid, '기대 낮춰보기', '해야 할 일을 모두 붙잡기보다 지금 중요한 한 가지를 골라봅니다.', '오늘 해야 할 일 중 가장 중요한 한 가지만 선택해보세요.', 'ACTION', 'ACTION_REFLECTION', 5, 'LOW', '["한 가지만 고르니 마음이 어떻게 달라졌나요?","여전히 부담스럽다면 무엇이 어려웠나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('a633fc1f-d7f3-5534-9c26-babfeecde617'::uuid, 'CHECK_MY_STANDARD', 1, 'df555650-f131-5fcc-8f9d-f9ca6d573ee8'::uuid, '내 기준 확인하기', '결정 속에서 타인의 기대와 나의 바람을 잠시 나누어봅니다.', '결정을 앞두고 있다면 ‘나는 무엇을 원하는가’를 적어보세요.', 'QUESTION', 'TEXT', 5, 'MEDIUM', '["다른 사람의 기대를 제외하면 무엇을 선택하고 싶은가요?","지금의 나에게 중요한 것은 무엇인가요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('764b13eb-22db-5b3f-938b-e5d90ec7af42'::uuid, 'REST_FIVE', 1, '2c789c3f-d1a7-5d64-b07a-4c847c9523c9'::uuid, '작은 회복 실험', '짧게 멈추는 일이 현재의 몸과 마음에 어떤 영향을 주는지 살펴봅니다.', '가능하다면 5분 동안 아무것도 하지 않고 쉬어보세요.', 'ACTION', 'ACTION_REFLECTION', 5, 'LOW', '["쉬는 동안 불편함이 있었나요?","쉬고 난 뒤 에너지나 감정이 달라졌나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('461085b3-e05d-5aeb-ac50-bd4155aaf8de'::uuid, 'EXPAND_GRATITUDE', 1, 'b0dc96d8-76c6-519a-bd67-773174ba72ee'::uuid, '감사 확장하기', '감사한 사건뿐 아니라 그 경험이 나에게 중요했던 이유를 남깁니다.', '감사하거나 다행이었던 일과, 그것이 중요했던 이유를 함께 적어보세요.', 'RECORD', 'TEXT', 4, 'LOW', '["그 경험에서 어떤 마음이나 필요가 채워졌나요?"]'::jsonb, '["친구가 연락해줘서 감사했다. 혼자가 아니라는 느낌이 들어 중요했다."]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('fa057004-6dad-50ca-b0d2-e2bb1df717a2'::uuid, 'NAME_NEED', 1, 'd69d7ad3-c7ab-5f8f-8b17-753068e3c663'::uuid, '지금 필요한 것 이름 붙이기', '해결책을 정하기 전에 지금 필요한 것을 짧게 확인합니다.', '지금 나에게 필요한 것을 한두 단어로 적어보세요.', 'QUESTION', 'TEXT', 3, 'LOW', '["그 필요를 아주 작게 채울 방법이 있을까요?"]'::jsonb, '["휴식","이해","거리","정리","안정"]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('e1b2da87-71dc-5bde-983d-c13e19031645'::uuid, 'EMOTION_ACTION', 1, 'd69d7ad3-c7ab-5f8f-8b17-753068e3c663'::uuid, '감정과 행동 연결하기', '감정 뒤에 이어진 행동을 좋고 나쁨으로 평가하지 않고 함께 봅니다.', '오늘 느낀 감정 하나와 그 뒤에 했던 행동을 함께 적어보세요.', 'OBSERVATION', 'TEXT', 4, 'LOW', '["그 행동은 그때의 나를 어떻게 도왔나요?"]'::jsonb, '["감정: 답답함 / 행동: 연락을 미룸"]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('ec9dc977-0d8d-5fc9-8d7d-35553b7379ea'::uuid, 'BODY_SIGNAL', 1, 'd69d7ad3-c7ab-5f8f-8b17-753068e3c663'::uuid, '몸의 신호 확인하기', '감정보다 먼저 나타났을 수 있는 몸의 변화를 살펴봅니다.', '오늘 몸에서 가장 먼저 느껴진 신호 하나를 적어보세요.', 'OBSERVATION', 'TEXT', 3, 'LOW', '["어깨, 호흡, 속, 손, 몸의 무게감 중 가까운 것이 있나요?"]'::jsonb, '["어깨가 굳음","숨이 짧아짐","손에 힘이 들어감"]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('b017163d-5676-53bf-b682-29f0890ba087'::uuid, 'SMALL_RELIEF', 1, 'b0dc96d8-76c6-519a-bd67-773174ba72ee'::uuid, '사소한 다행 찾기', '완벽하지 않았던 하루 안에서도 남아 있는 작은 다행을 봅니다.', '오늘 완벽하지는 않았지만 다행이었던 일 하나를 적어보세요.', 'RECORD', 'TEXT', 3, 'LOW', '["그 일이 왜 다행이라고 느껴졌나요?"]'::jsonb, '["늦었지만 결국 연락했다.","모든 일을 하진 못했지만 하나는 끝냈다."]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('936df01e-9415-5c20-a489-cd5f4774c698'::uuid, 'DROP_ONE', 1, '2cf1dc3f-1c78-556f-925b-b45125f5e95a'::uuid, '한 가지 덜어내기', '지금 하지 않아도 되는 일을 구분해 부담을 낮춰봅니다.', '오늘 하지 않아도 되는 일 하나를 정해보세요.', 'ACTION', 'ACTION_REFLECTION', 3, 'LOW', '["내려놓으니 어떤 느낌이 들었나요?","실제로 미뤄도 괜찮았나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('22518977-c06a-5c72-9c80-8af41406d832'::uuid, 'START_THREE_MIN', 1, '2cf1dc3f-1c78-556f-925b-b45125f5e95a'::uuid, '3분만 시작하기', '일을 많이 끝내기보다 나의 시작 조건을 알아봅니다.', '미뤄둔 일 하나를 3분 동안만 해보세요. 3분 뒤 멈춰도 괜찮아요.', 'ACTION', 'ACTION_REFLECTION', 3, 'LOW', '["시작 전과 후의 느낌이 달랐나요?","3분 뒤 계속하고 싶었나요?","무엇이 시작을 도왔나요?"]'::jsonb, '["문서 열기","책 한 쪽 읽기","사진 세 장 정리하기"]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('5522320a-8d15-5d59-819b-54f36d7829fa'::uuid, 'START_CONDITION', 1, '2cf1dc3f-1c78-556f-925b-b45125f5e95a'::uuid, '시작 조건 알아보기', '무언가를 시작할 수 있었던 순간의 구체적인 조건을 찾습니다.', '오늘 시작할 수 있었던 일이 있다면 그때의 조건을 적어보세요.', 'OBSERVATION', 'TEXT', 4, 'LOW', '["사람, 시간 제한, 준비된 도구, 구체적인 첫 단계 중 무엇이 있었나요?"]'::jsonb, '["도구가 미리 준비되어 있었음","해야 할 일이 구체적이었음"]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('393b35ea-c150-5d46-ba45-281c3f4d81da'::uuid, 'REDUCE_DISTRACTION', 1, '6dd18c38-af04-52bc-9eae-f73773d92710'::uuid, '방해 요인 하나 줄이기', '집중을 요구하기보다 주변의 방해 요소 하나를 줄여봅니다.', '지금 하려는 일을 방해하는 것 하나를 잠시 치워보세요.', 'ACTION', 'ACTION_REFLECTION', 3, 'LOW', '["무엇을 바꿨나요?","집중이나 마음에 달라진 점이 있었나요?"]'::jsonb, '["휴대폰 뒤집어두기","브라우저 탭 하나 닫기"]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('82c2e4ae-7f32-5109-96b9-78c02de193f9'::uuid, 'TIDY_THREE', 1, '29d3e25a-3f99-5de0-80ec-59cc603b9dc3'::uuid, '물건 세 개 정리하기', '공간 전체가 아니라 눈앞의 물건 세 개만 바꿔봅니다.', '당장 필요하지 않은 물건 세 개만 정리해보세요.', 'ACTION', 'ACTION_REFLECTION', 4, 'LOW', '["정리 전후의 마음이나 집중이 달라졌나요?","유지하고 싶은 변화가 있나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('67a68acc-48f8-54e8-9f26-b667c491dae5'::uuid, 'SET_STOP_POINT', 1, '2cf1dc3f-1c78-556f-925b-b45125f5e95a'::uuid, '멈출 시점 정하기', '끝까지 해야 한다는 부담 대신 어디에서 멈출지 먼저 정합니다.', '일을 시작하기 전에 어디까지 하고 멈출지 정해보세요.', 'QUESTION', 'TEXT', 3, 'LOW', '["멈출 곳을 정하니 시작이 조금 쉬워졌나요?"]'::jsonb, '["문단 하나","5분","서랍 한 칸"]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('1efe0673-0a33-5dcd-a2b2-a7748ab2fb8d'::uuid, 'ATTACH_CUE', 1, '34474694-da41-5a99-9108-aecfd21a5de4'::uuid, '잊기 쉬운 행동에 단서 붙이기', '의지보다 이미 반복되는 행동과 눈에 보이는 단서를 활용합니다.', '잊기 쉬운 행동 하나를 고르고, 기존 행동·물건 위치·알림 중 단서 하나를 붙여보세요.', 'ACTION', 'ACTION_REFLECTION', 5, 'LOW', '["어떤 단서가 가장 자연스러웠나요?","잊었을 때 다시 돌아올 방법은 무엇인가요?"]'::jsonb, '["칫솔질 후 물 마시기","현관 앞에 필요한 물건 두기"]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('108598e9-e5f3-59bb-97f4-7ffa90a38ed9'::uuid, 'ENERGY_USE', 1, '2c789c3f-d1a7-5d64-b07a-4c847c9523c9'::uuid, '오늘의 에너지 사용처 보기', '오늘 에너지가 어디에 많이 쓰였는지 판단 없이 살펴봅니다.', '오늘 에너지를 가장 많이 쓴 일을 적어보세요.', 'OBSERVATION', 'TEXT', 4, 'LOW', '["예상보다 에너지가 많이 들었나요?","그 이유로 떠오르는 조건이 있나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('083d3995-d2c7-5327-89fb-fb05aa937799'::uuid, 'ENERGY_RETURN', 1, '2c789c3f-d1a7-5d64-b07a-4c847c9523c9'::uuid, '에너지를 돌려준 것 찾기', '에너지를 조금이라도 돌려준 순간이나 행동을 찾습니다.', '오늘 에너지를 조금이라도 돌려준 것을 적어보세요.', 'REVIEW', 'TEXT', 4, 'LOW', '["다시 해볼 만한 것이 있었나요?"]'::jsonb, '["혼자 있는 시간","산책","샤워","대화"]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('15b045c4-4fff-54dd-b573-cf566efdc2fa'::uuid, 'WAIT_ONE_BEAT', 1, '34132496-1861-5a71-9311-0e6f52b4f743'::uuid, '말하기 전에 한 박자 기다리기', '대화에서 바로 말하고 싶은 순간을 짧게 관찰합니다.', '가능한 대화에서 바로 말하고 싶어진 순간에 한 번 숨을 고르고 기다려보세요.', 'ACTION', 'ACTION_REFLECTION', 5, 'LOW', '["기다리는 동안 어떤 생각이 들었나요?","상대의 말을 조금 더 들을 수 있었나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('cc2936cc-5719-53c9-8dad-fbf000599dbf'::uuid, 'WRITE_WANTED_WORDS', 1, '3f3fba80-3277-59ed-ac3a-7e8f88d7b773'::uuid, '듣고 싶은 말 직접 적기', '누군가에게 듣고 싶었던 말을 먼저 자신의 언어로 확인합니다.', '오늘 듣고 싶었던 말을 한 문장으로 적어보세요.', 'RECORD', 'TEXT', 3, 'LOW', '["그 말을 지금의 나에게 건넨다면 어떤 느낌인가요?"]'::jsonb, '["그럴 수 있어.","조금 쉬어도 괜찮아."]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('c033304d-bc33-52c3-9d24-80526986c3b8'::uuid, 'MISUNDERSTOOD_MOMENT', 1, '34132496-1861-5a71-9311-0e6f52b4f743'::uuid, '의도와 다르게 전해졌던 순간', '상대의 마음을 단정하지 않고 내 의도와 전달된 가능성을 나누어봅니다.', '내 의도와 다르게 받아들여졌다고 느낀 순간 하나를 적어보세요.', 'RECORD', 'TEXT', 5, 'MEDIUM', '["나는 무엇을 의도했나요?","다시 말한다면 어떻게 표현하고 싶나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('07040105-1a03-5193-8604-9a76eeddc10b'::uuid, 'FACT_INTERPRETATION', 1, 'fa04e69d-1015-59d3-b486-f1bf8583263c'::uuid, '사실과 해석 나누기', '생각을 틀렸다고 판단하지 않고 확인된 사실과 나의 해석을 나눕니다.', '마음이 상했던 일을 ‘확인된 사실’과 ‘내가 한 해석’으로 나누어 적어보세요.', 'QUESTION', 'FACT_AND_INTERPRETATION', 5, 'MEDIUM', '["사실만 남기면 무엇이 보이나요?"]'::jsonb, '["사실: 메시지에 하루 답이 없었다. / 해석: 나와 이야기하기 싫어진 것 같다."]'::jsonb, '{"type":"object","properties":{"fact":{"type":"string","maxLength":700},"interpretation":{"type":"string","maxLength":700},"otherPossibility":{"type":"string","maxLength":700}},"additionalProperties":false}'::jsonb, NULL),
    ('fd9cf001-1b83-5a5a-8019-2eaa572d04b0'::uuid, 'ONE_MORE_POSSIBILITY', 1, 'fa04e69d-1015-59d3-b486-f1bf8583263c'::uuid, '다른 가능성 하나 생각하기', '기존 생각을 지우지 않고 설명의 가능성을 하나 더 열어둡니다.', '지금 떠오른 해석 외에 가능한 설명을 하나 더 적어보세요.', 'QUESTION', 'TEXT', 4, 'MEDIUM', '["새 가능성을 적었을 때 기존 감정이 달라졌나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('80afc8f6-48ef-5b4b-a7e5-93a1058e237e'::uuid, 'FINISH_IMPERFECTLY', 1, '89c16867-28e4-5363-9f1b-2bec8a55bd45'::uuid, '완벽하지 않은 채 마무리하기', '완벽하지 않아도 되는 일의 적당한 마침점을 실험합니다.', '완벽하게 끝내지 않아도 되는 일 하나를 적당한 상태에서 멈춰보세요.', 'ACTION', 'ACTION_REFLECTION', 5, 'LOW', '["멈추는 것이 불편했나요?","결과는 실제로 어느 정도 괜찮았나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('ea0f9b7d-adec-545b-9135-c56adac84647'::uuid, 'REVIEW_UNFINISHED_PLAN', 1, '2cf1dc3f-1c78-556f-925b-b45125f5e95a'::uuid, '계획대로 되지 않았던 일 다시 보기', '실패나 의지 부족으로 결론 내리기 전에 당시의 조건을 살펴봅니다.', '최근 계획대로 진행되지 않았던 일 하나와 영향을 준 조건을 적어보세요.', 'QUESTION', 'TEXT_AND_OPTIONS', 6, 'MEDIUM', '["시간, 에너지, 시작 단계, 방해 요소, 우선순위 중 무엇이 영향을 주었나요?","다음에 바꿔볼 조건 하나가 있나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000},"selectedOptions":{"type":"array","maxItems":8,"items":{"type":"string","maxLength":80}}},"additionalProperties":false}'::jsonb, NULL),
    ('d2ce46b7-bdd5-544d-adb3-7ea3ba9278c0'::uuid, 'PRAISE_EVIDENCE', 1, '89c16867-28e4-5363-9f1b-2bec8a55bd45'::uuid, '칭찬의 근거 찾기', '타인의 평가보다 그 말의 근거가 된 실제 행동을 남깁니다.', '최근 들었던 좋은 피드백과 그 근거가 된 나의 행동을 적어보세요.', 'QUESTION', 'TEXT', 5, 'MEDIUM', '["칭찬이 없어도 남는 사실은 무엇인가요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('cceaf746-7512-5a12-9e97-604d1835871c'::uuid, 'GOOD_CHOICE', 1, '89c16867-28e4-5363-9f1b-2bec8a55bd45'::uuid, '오늘 잘한 선택 하나 찾기', '결과와 상관없이 내가 괜찮았다고 느끼는 선택을 확인합니다.', '오늘 잘 선택했다고 느끼는 것 하나를 적어보세요.', 'RECORD', 'TEXT', 3, 'LOW', '["왜 그렇게 느꼈나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('9b6334c7-aa65-5c70-9b40-65aefa2836df'::uuid, 'KINDER_WORDS', 1, '89c16867-28e4-5363-9f1b-2bec8a55bd45'::uuid, '나에게 친절한 표현으로 바꾸기', '스스로에게 한 모진 말을 현실을 지우지 않는 조금 덜 가혹한 표현으로 바꿉니다.', '오늘 스스로에게 했던 모진 말 하나를 조금 덜 가혹한 표현으로 바꿔보세요.', 'QUESTION', 'TEXT', 4, 'MEDIUM', '["바꿔 적으니 느낌이 달라졌나요?"]'::jsonb, '["나는 왜 이것도 못하지 → 오늘은 시작할 에너지가 부족했던 것 같다."]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('23906a97-ddf9-53ce-8a84-819d89c7c5de'::uuid, 'OBSERVE_TRAIT', 1, 'f60e0e2d-e3c8-50b4-aa77-7816a90c055d'::uuid, '나의 특성 하나 관찰하기', '특성을 성격이나 진단으로 확정하지 않고 오늘의 실제 상황에서 봅니다.', '자주 보인다고 느끼는 특성 하나가 오늘 어떻게 나타났는지 적어보세요.', 'OBSERVATION', 'TEXT', 4, 'LOW', '["도움이 된 면과 어려웠던 면이 함께 있었나요?"]'::jsonb, '["새로운 일에 흥미가 생김","시작까지 시간이 오래 걸림"]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('74c8edf6-74f0-5867-bb74-419eeff4e37c'::uuid, 'HELPFUL_ENVIRONMENT', 1, '29d3e25a-3f99-5de0-80ec-59cc603b9dc3'::uuid, '도움이 된 환경 찾기', '집중하거나 편안해지는 데 도움이 된 환경의 단서를 찾습니다.', '오늘 집중하거나 편안해지는 데 도움이 된 환경 하나를 적어보세요.', 'OBSERVATION', 'TEXT', 4, 'LOW', '["소리, 밝기, 사람, 정돈 상태 중 무엇이 영향을 주었나요?"]'::jsonb, '["조용한 공간","사람이 있는 카페","정리된 책상"]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('fcff9bb3-a666-5d0c-ba60-fe3878ce92a5'::uuid, 'NOT_A_FIT_METHOD', 1, 'f60e0e2d-e3c8-50b4-aa77-7816a90c055d'::uuid, '나에게 맞지 않은 방법 인정하기', '맞지 않았던 방법도 자기이해의 자료로 남깁니다.', '해봤지만 나와 잘 맞지 않았던 방법 하나를 적어보세요.', 'REVIEW', 'TEXT', 5, 'MEDIUM', '["무엇이 불편했나요?","어떤 방식이라면 조금 더 나을까요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('323b0350-5065-58bd-b2ea-01cc6382614b'::uuid, 'ONE_LINE_DIARY', 1, 'f60e0e2d-e3c8-50b4-aa77-7816a90c055d'::uuid, '한 문장 일기', '길게 쓰지 않고 오늘의 인상을 한 문장으로 남깁니다.', '오늘 하루를 한 문장으로만 적어보세요.', 'RECORD', 'TEXT', 2, 'LOW', '["이 문장에서 가장 마음에 남는 단어는 무엇인가요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('08dee776-a127-514d-8234-fadf769b9d71'::uuid, 'REVIEW_THREE_PHOTOS', 1, 'f60e0e2d-e3c8-50b4-aa77-7816a90c055d'::uuid, '사진 세 장 돌아보기', '개인 사진첩의 최근 사진을 단서로 기억과 감정을 돌아봅니다.', '사진첩에서 오늘 또는 최근 사진 세 장을 보고 떠오른 감정을 텍스트로 적어보세요.', 'RECORD', 'TEXT', 5, 'LOW', '["세 장에 공통으로 남은 분위기가 있었나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, 'Beta 1에서는 사진을 서버에 업로드하지 않고 텍스트만 저장합니다.'),
    ('be2f80a3-2c7b-52a3-8e7b-0a40ac0caa18'::uuid, 'FAVORITE_SENSE', 1, '2c789c3f-d1a7-5d64-b07a-4c847c9523c9'::uuid, '좋아하는 감각 찾기', '편안하거나 기분 좋았던 감각의 단서를 찾습니다.', '오늘 편안하거나 기분 좋았던 감각 하나를 적어보세요.', 'OBSERVATION', 'TEXT', 3, 'LOW', '["온도, 촉감, 향, 소리, 빛 중 가까운 것이 있나요?"]'::jsonb, '["따뜻한 온도","빗소리","시원한 바람"]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('db249046-284f-541c-bed7-fea508753674'::uuid, 'WALK_FIVE', 1, '2c789c3f-d1a7-5d64-b07a-4c847c9523c9'::uuid, '5분 걷기', '운동 성과가 아니라 움직이기 전후의 감정과 에너지를 관찰합니다.', '몸 상태가 괜찮다면 5분 동안 천천히 걸어보세요.', 'ACTION', 'ACTION_REFLECTION', 5, 'LOW', '["걷기 전과 후의 감정이나 에너지가 달랐나요?","부담스럽지는 않았나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, '통증이나 불편함이 있으면 하지 않거나 다른 미션으로 바꿀 수 있습니다.'),
    ('268185a8-bee0-5442-8a22-64141acc4dca'::uuid, 'LISTEN_ONE_SONG', 1, '2c789c3f-d1a7-5d64-b07a-4c847c9523c9'::uuid, '한 곡 온전히 듣기', '다른 일을 잠시 멈추고 한 곡에 머물러봅니다.', '음악 한 곡을 다른 일을 하지 않고 들어보세요.', 'ACTION', 'ACTION_REFLECTION', 5, 'LOW', '["집중이 되었나요?","어떤 감정이 떠올랐나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('00ac3dbd-190a-5601-9d0d-a67a7c44cec6'::uuid, 'PREPARE_ONE_THING', 1, '34474694-da41-5a99-9108-aecfd21a5de4'::uuid, '내일을 위한 한 가지 준비', '내일의 시작을 돕는 아주 작은 준비를 남깁니다.', '내일의 나를 위해 작은 것 하나를 미리 준비해두세요.', 'ACTION', 'ACTION_REFLECTION', 4, 'LOW', '["준비해두니 마음이 어떻게 달라졌나요?"]'::jsonb, '["옷 꺼내두기","해야 할 일의 첫 단계 적기"]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('11e1c7bf-9cec-5234-968e-7ca1b4bcf850'::uuid, 'FIND_FIXED_ACTION', 1, '34474694-da41-5a99-9108-aecfd21a5de4'::uuid, '고정된 행동 찾기', '새 습관을 만들기 전에 이미 반복되는 행동을 기준점으로 찾습니다.', '매일 거의 빠지지 않고 하는 행동 하나를 적어보세요.', 'OBSERVATION', 'TEXT', 3, 'LOW', '["새 행동을 연결한다면 어느 뒤가 자연스러울까요?"]'::jsonb, '["양치하기","출근 후 가방 내려놓기"]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('b32e6835-3fd0-576e-855b-00c0ef281ffb'::uuid, 'CHOOSE_REST', 1, '2c789c3f-d1a7-5d64-b07a-4c847c9523c9'::uuid, '오늘은 쉬기로 선택하기', '하지 못함이 아니라 쉬기로 한 선택과 그때의 마음을 기록합니다.', '오늘 쉬기로 선택한 일과 그 이유를 적어보세요.', 'RECORD', 'TEXT', 3, 'LOW', '["죄책감이나 불편함이 있었나요?","쉬는 것이 실제로 도움이 되었나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('d531adc6-baf4-558d-9c50-02bcdcaf2583'::uuid, 'THREE_TRAITS', 1, 'f60e0e2d-e3c8-50b4-aa77-7816a90c055d'::uuid, '나라고 느끼는 특성 세 가지', '자신을 유형화하지 않고 자주 보인다고 느끼는 특성을 자신의 말로 적습니다.', '내가 자주 보인다고 느끼는 특성 세 가지를 적어보세요.', 'RECORD', 'BULLET_LIST', 6, 'MEDIUM', '["각 특성이 나타났던 실제 상황이 있나요?","도움이 된 때와 어려웠던 때가 함께 있었나요?"]'::jsonb, '["흥미가 생긴 일에는 오래 몰입함","새로운 것을 시작할 때 에너지가 생김"]'::jsonb, '{"type":"object","properties":{"items":{"type":"array","maxItems":7,"items":{"type":"string","maxLength":250}}},"additionalProperties":false}'::jsonb, NULL),
    ('792c75d9-813c-51c2-a43f-7f6208330e30'::uuid, 'THREE_MIN_ROUTINE', 1, '34474694-da41-5a99-9108-aecfd21a5de4'::uuid, '하루 3분 사소한 행동', '생산성과 관계없이 3분 행동이 나에게 어떤 영향을 주는지 봅니다.', '3분 동안 해보고 싶은 사소한 행동 하나를 골라 해보세요.', 'ACTION', 'ACTION_REFLECTION', 3, 'LOW', '["시작하기는 어땠나요?","기분이나 에너지에 변화가 있었나요?","다시 해보고 싶은가요?"]'::jsonb, '["키캡 만지기","반려동물 추억 한 줄 적기","창밖 바라보기"]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('d15348f3-c277-5f8d-bfa0-122d36a71281'::uuid, 'LOOK_AT_THOUGHT_FRAME', 1, 'fa04e69d-1015-59d3-b486-f1bf8583263c'::uuid, '생각의 틀 살펴보기', '생각을 오류로 판정하지 않고 상황 전체를 설명하는지 한 걸음 떨어져 봅니다.', '최근 마음이 상했던 순간과 그때 떠오른 생각을 적어보세요.', 'QUESTION', 'FACT_AND_INTERPRETATION', 6, 'HIGH', '["확인된 사실은 무엇인가요?","다른 가능한 설명이 있나요?"]'::jsonb, '["전부 아니면 아무것도 아니라고 느끼기","상대 생각을 확인하지 않고 예상하기"]'::jsonb, '{"type":"object","properties":{"fact":{"type":"string","maxLength":700},"interpretation":{"type":"string","maxLength":700},"otherPossibility":{"type":"string","maxLength":700}},"additionalProperties":false}'::jsonb, NULL),
    ('237d2b9d-3dbc-55f2-a91f-7f282545da8d'::uuid, 'MORNING_START', 1, '34474694-da41-5a99-9108-aecfd21a5de4'::uuid, '나에게 맞는 아침 시작', '완벽한 모닝 루틴이 아니라 내일 아침을 돕는 조건을 시험합니다.', '내일 아침 해보고 싶은 작은 행동 한두 가지를 고르고 필요한 것을 미리 준비해보세요.', 'ACTION', 'ACTION_REFLECTION', 6, 'LOW', '["실행 여부보다 무엇이 도움 되거나 방해됐나요?","다음에는 한 가지만 유지하거나 바꾼다면요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('8e84b582-1cac-5474-9ff6-7c83c8f94012'::uuid, 'LATE_SLEEP_CONDITIONS', 1, '34474694-da41-5a99-9108-aecfd21a5de4'::uuid, '늦게 잠든 날의 조건 살펴보기', '늦게 잠든 이유를 의지나 질환으로 단정하지 않고 당시의 조건을 살펴봅니다.', '최근 늦게 잠든 날에 무엇을 했고 어떤 생각과 감정이 있었는지 적어보세요.', 'OBSERVATION', 'TEXT', 6, 'MEDIUM', '["몰입, 반복되는 생각, 혼자만의 시간, 주변 환경 중 가까운 것이 있나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('cad716b3-592e-5225-9642-a1b44eb61f66'::uuid, 'EMOTION_SIGNAL', 1, 'd69d7ad3-c7ab-5f8f-8b17-753068e3c663'::uuid, '감정의 신호 알아차리기', '크게 느껴진 감정이 몸, 생각, 행동에 남긴 신호를 살펴봅니다.', '최근 감정이 크게 느껴진 순간의 몸, 생각, 행동 변화를 적어보세요.', 'OBSERVATION', 'TEXT', 6, 'HIGH', '["그때 필요했던 것은 무엇이었나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('3d3cf321-50ee-5e0f-9fe4-637e26eecac4'::uuid, 'REVIEW_HURTFUL_WORDS', 1, '3f3fba80-3277-59ed-ac3a-7e8f88d7b773'::uuid, '흔들렸던 말 다시 살펴보기', '상대의 의도를 단정하지 않고 사실, 해석, 책임과 경계를 나누어봅니다.', '다른 사람의 말이나 행동으로 불편했던 일을 적어보세요.', 'QUESTION', 'FACT_AND_INTERPRETATION', 7, 'HIGH', '["확인된 사실과 나의 해석은 무엇인가요?","내가 책임질 부분과 상대의 몫은 어디까지인가요?","앞으로 필요한 경계가 있나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"fact":{"type":"string","maxLength":700},"interpretation":{"type":"string","maxLength":700},"otherPossibility":{"type":"string","maxLength":700}},"additionalProperties":false}'::jsonb, NULL),
    ('0e3bdfd4-a4c6-51ba-87f9-4f4527e30018'::uuid, 'THREE_BULLETS', 1, '6dd18c38-af04-52bc-9eae-f73773d92710'::uuid, '머릿속 항목 세 줄로 꺼내기', '복잡한 불렛저널 대신 지금 머릿속에 있는 항목 세 개만 꺼냅니다.', '지금 떠오르는 일이나 생각을 짧은 점 문장 세 개로 적어보세요.', 'RECORD', 'BULLET_LIST', 3, 'LOW', '["오늘, 곧, 나중에로 나누고 싶은 항목이 있나요?","오늘 하지 않아도 되는 항목이 있나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"items":{"type":"array","maxItems":7,"items":{"type":"string","maxLength":250}}},"additionalProperties":false}'::jsonb, NULL),
    ('fa31cec7-e046-590c-b11e-5137679056bf'::uuid, 'MOVE_AND_NOTICE', 1, '2c789c3f-d1a7-5d64-b07a-4c847c9523c9'::uuid, '몸을 움직인 뒤 살펴보기', '현재 몸 상태에 무리가 없는 움직임 뒤의 변화를 관찰합니다.', '몸 상태가 괜찮다면 3~5분 동안 가볍게 스트레칭하거나 움직여보세요.', 'ACTION', 'ACTION_REFLECTION', 5, 'LOW', '["전후의 감정과 에너지가 달라졌나요?","집중 정도와 부담감은 어땠나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, '통증이나 의료적 제한이 있으면 하지 않거나 다른 미션으로 교체합니다.'),
    ('32872886-eadc-50c8-bd0c-5b8168a3886d'::uuid, 'SMALLEST_STEP', 1, '2cf1dc3f-1c78-556f-925b-b45125f5e95a'::uuid, '가장 작은 첫 단계로 나누기', '해야 할 일을 바로 끝내려 하지 않고 시작할 수 있는 첫 단계로 줄입니다.', '해야 할 일 하나를 3분 안에 시작할 수 있는 가장 작은 단계로 나누어보세요.', 'ACTION', 'ACTION_REFLECTION', 5, 'LOW', '["첫 단계는 구체적으로 무엇인가요?","필요한 도구를 미리 준비할 수 있나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"attempted":{"type":"boolean"},"before":{"type":"string","maxLength":300},"after":{"type":"string","maxLength":300},"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('1d003a7b-c01f-5993-a7bd-4992099dc4be'::uuid, 'WANTED_INTENT', 1, '34132496-1861-5a71-9311-0e6f52b4f743'::uuid, '전하고 싶었던 의도 정리하기', '대화에서 실제로 전하고 싶었던 뜻을 상대의 의도와 분리해 정리합니다.', '마음에 남은 대화에서 내가 전하고 싶었던 의도를 적어보세요.', 'QUESTION', 'TEXT', 5, 'MEDIUM', '["다시 말한다면 어떤 표현을 사용하고 싶나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"note":{"type":"string","maxLength":1000}},"additionalProperties":false}'::jsonb, NULL),
    ('fcd20e22-4360-52b7-b92b-99c9d86e2c21'::uuid, 'COURSE_DISCOVERY_REVIEW', 1, 'f60e0e2d-e3c8-50b4-aa77-7816a90c055d'::uuid, '기억에 남은 발견 정리하기', '코스의 수행 결과보다 기억에 남은 시도와 발견을 한 문장으로 남깁니다.', '이번 작은 실험에서 기억에 남은 경험이나 발견을 한 문장으로 적어보세요.', 'REVIEW', 'COURSE_REVIEW', 6, 'LOW', '["가장 부담이 적었던 미션은 무엇이었나요?","나와 맞지 않았던 방법이 있었나요?","이어가고 싶은 조건이 있나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"discovery":{"type":"string","maxLength":1000},"helpfulConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"difficultConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"continueAction":{"type":"string","maxLength":500}},"additionalProperties":false}'::jsonb, NULL),
    ('6ae9f293-3daa-581a-af37-8a719b206ae5'::uuid, 'START_METHOD_REVIEW', 1, '2cf1dc3f-1c78-556f-925b-b45125f5e95a'::uuid, '나에게 맞았던 시작 방법 정리하기', '이번 코스에서 시작을 도운 구체적인 조건을 정리합니다.', '가장 편했던 시작 방법과 앞으로 유지하고 싶은 조건 하나를 적어보세요.', 'REVIEW', 'COURSE_REVIEW', 6, 'LOW', '["어려웠던 조건도 함께 있었나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"discovery":{"type":"string","maxLength":1000},"helpfulConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"difficultConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"continueAction":{"type":"string","maxLength":500}},"additionalProperties":false}'::jsonb, NULL),
    ('e07cbbbf-a9dc-52e2-9aba-48cf5c5adaab'::uuid, 'RECOVERY_METHOD_REVIEW', 1, '2c789c3f-d1a7-5d64-b07a-4c847c9523c9'::uuid, '회복에 도움이 된 방법 정리하기', '이번 코스에서 실제로 도움이 된 회복 방법과 맞지 않았던 방법을 나눕니다.', '가장 회복에 도움이 된 방법과 다음에도 이어가고 싶은 것을 적어보세요.', 'REVIEW', 'COURSE_REVIEW', 6, 'LOW', '["부담스럽거나 맞지 않았던 방법은 무엇이었나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"discovery":{"type":"string","maxLength":1000},"helpfulConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"difficultConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"continueAction":{"type":"string","maxLength":500}},"additionalProperties":false}'::jsonb, NULL),
    ('183c8ac3-19c3-58b0-9ca7-479d13ebbce5'::uuid, 'EMOTION_NEED_REVIEW', 1, 'd69d7ad3-c7ab-5f8f-8b17-753068e3c663'::uuid, '반복된 감정과 필요 돌아보기', '코스 기록에서 반복된 감정과 필요를 가능성으로 정리합니다.', '여러 날의 기록에서 반복해 등장한 감정과 필요를 적어보세요.', 'REVIEW', 'COURSE_REVIEW', 6, 'LOW', '["예상했던 것과 달랐던 점이 있나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"discovery":{"type":"string","maxLength":1000},"helpfulConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"difficultConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"continueAction":{"type":"string","maxLength":500}},"additionalProperties":false}'::jsonb, NULL),
    ('26255d75-bacc-55fc-9769-abe64aac4b58'::uuid, 'SELF_TRUST_REVIEW', 1, '89c16867-28e4-5363-9f1b-2bec8a55bd45'::uuid, '새롭게 인정하고 싶은 점 적기', '타인의 평가가 아니라 내 행동과 선택에서 남은 근거를 한 문장으로 정리합니다.', '나에 대해 새롭게 인정하고 싶은 점을 한 문장으로 적어보세요.', 'REVIEW', 'COURSE_REVIEW', 6, 'LOW', '["그 문장의 근거가 된 실제 행동은 무엇인가요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"discovery":{"type":"string","maxLength":1000},"helpfulConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"difficultConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"continueAction":{"type":"string","maxLength":500}},"additionalProperties":false}'::jsonb, NULL),
    ('cc588164-9957-5a0c-8409-bf609f43c544'::uuid, 'CONVERSATION_REVIEW', 1, '34132496-1861-5a71-9311-0e6f52b4f743'::uuid, '원하는 대화 방식 정리하기', '관계의 정답보다 앞으로 시도하고 싶은 대화 방식과 경계를 정리합니다.', '앞으로 원하는 대화 방식과 한 번 시도해볼 표현을 적어보세요.', 'REVIEW', 'COURSE_REVIEW', 6, 'LOW', '["내 책임과 상대의 몫을 어떻게 나누고 싶나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"discovery":{"type":"string","maxLength":1000},"helpfulConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"difficultConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"continueAction":{"type":"string","maxLength":500}},"additionalProperties":false}'::jsonb, NULL),
    ('7fcfc8e6-75b9-57e2-8592-7e288120bc53'::uuid, 'LIFE_RHYTHM_REVIEW', 1, '34474694-da41-5a99-9108-aecfd21a5de4'::uuid, '나에게 맞는 생활 리듬 정리하기', '지키지 못한 날을 평가하지 않고 도움이 된 단서와 돌아오는 방법을 정리합니다.', '이번 코스에서 가장 자연스러웠던 생활 단서와 놓쳤을 때 돌아올 방법을 적어보세요.', 'REVIEW', 'COURSE_REVIEW', 6, 'LOW', '["알림, 위치, 고정 행동 중 무엇이 가장 도움이 되었나요?"]'::jsonb, '[]'::jsonb, '{"type":"object","properties":{"discovery":{"type":"string","maxLength":1000},"helpfulConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"difficultConditions":{"type":"array","maxItems":5,"items":{"type":"string","maxLength":200}},"continueAction":{"type":"string","maxLength":500}},"additionalProperties":false}'::jsonb, NULL);

INSERT INTO experiment_programs
    (id, code, content_version, primary_topic_id, title, description, duration_days,
     source_type, status, estimated_minutes_min, estimated_minutes_max,
     is_featured, is_beginner, display_order)
VALUES
    ('4bc6717b-2220-502d-859f-90a699b43e6d'::uuid, 'NOW_MIND_3', 1, 'd69d7ad3-c7ab-5f8f-8b17-753068e3c663'::uuid, '지금의 마음 알아보기', '감정, 몸의 신호, 지금 필요한 것을 차례로 살펴보는 입문 코스예요.', 3, 'TEMPLATE', 'PUBLISHED', 3, 3, true, true, 1),
    ('742c9335-1f49-571e-aaf3-98c349fb53ad'::uuid, 'LOWER_PRESSURE_3', 1, '2cf1dc3f-1c78-556f-925b-b45125f5e95a'::uuid, '부담 낮춰보기', '해야 할 일을 줄이고 작게 시작한 뒤, 덜어낼 것을 찾아보는 3일이에요.', 3, 'TEMPLATE', 'PUBLISHED', 3, 5, true, true, 2),
    ('a02a1543-8eb1-5839-82d6-8bc11a967b20'::uuid, 'RECOVERY_CLUES_3', 1, '2c789c3f-d1a7-5d64-b07a-4c847c9523c9'::uuid, '작은 회복 알아보기', '에너지가 어디로 가고 어디에서 조금 돌아오는지 살펴봐요.', 3, 'TEMPLATE', 'PUBLISHED', 4, 5, true, false, 3),
    ('6aea911d-112f-5021-95e0-42f3d1c69410'::uuid, 'ENVIRONMENT_LIGHT_3', 1, '29d3e25a-3f99-5de0-80ec-59cc603b9dc3'::uuid, '내 환경 가볍게 바꾸기', '집중과 편안함에 영향을 주는 환경을 관찰하고 작은 변화 하나를 시험해봐요.', 3, 'TEMPLATE', 'PUBLISHED', 3, 4, false, false, 4),
    ('36a9a319-cb8a-5cbb-b501-0554db70ff59'::uuid, 'LIFE_RHYTHM_CLUES_3', 1, '34474694-da41-5a99-9108-aecfd21a5de4'::uuid, '생활 리듬의 단서 찾기', '늦게 잠든 날, 반복 행동, 내일의 준비에서 나에게 맞는 리듬의 단서를 찾아봐요.', 3, 'TEMPLATE', 'PUBLISHED', 3, 6, false, false, 5),
    ('d065b063-c99b-59b7-a04c-413c36b13afe'::uuid, 'TRAITS_GENTLY_3', 1, 'f60e0e2d-e3c8-50b4-aa77-7816a90c055d'::uuid, '나의 특성을 가볍게 살펴보기', '나를 유형화하지 않고 내가 느끼는 특성과 실제 상황을 연결해봐요.', 3, 'TEMPLATE', 'PUBLISHED', 4, 6, false, false, 6),
    ('4fe7742e-30fa-5c9d-929e-2be5813d19e9'::uuid, 'KNOW_ME_LIGHTLY_7', 1, 'f60e0e2d-e3c8-50b4-aa77-7816a90c055d'::uuid, '가볍게 나를 알아보기', '처음 시작하는 분을 위한 코스예요. 매일 다른 질문으로 지금의 나를 가볍게 살펴봐요.', 7, 'TEMPLATE', 'PUBLISHED', 2, 6, true, true, 7),
