-- Integrity checks for Flyway execution.
DO $$
BEGIN
    IF (SELECT count(*) FROM experiment_topics) < 13 THEN
        RAISE EXCEPTION 'experiment topic seed is incomplete';
    END IF;
    IF (SELECT count(*) FROM experiment_missions) < 58 THEN
        RAISE EXCEPTION 'experiment mission seed is incomplete';
    END IF;
    IF (SELECT count(*) FROM experiment_programs) < 13 THEN
        RAISE EXCEPTION 'experiment program seed is incomplete';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM experiment_programs p
        LEFT JOIN experiment_program_missions pm ON pm.program_id = p.id
        GROUP BY p.id, p.duration_days
        HAVING count(pm.mission_id) <> p.duration_days
    ) THEN
        RAISE EXCEPTION 'each experiment program must have one mission per day';
    END IF;
END
$$;
